+<?php
+declare(strict_types=1);
+
+namespace WPMedia\BackWPup\Tracking;
+
+if ( ! defined( 'ABSPATH' ) ) {
+	exit;
+}
+
+use WPMedia\BackWPup\EventManagement\SubscriberInterface;
+
+/**
+ * Subscriber for nudge banner tracking events.
+ */
+class NudgeSubscriber implements SubscriberInterface {
+
+	/**
+	 * The nudge tracking service.
+	 *
+	 * @var NudgeTracking
+	 */
+	private $tracking;
+
+	/**
+	 * Constructor.
+	 *
+	 * @param NudgeTracking $tracking The nudge tracking service.
+	 */
+	public function __construct( NudgeTracking $tracking ) {
+		$this->tracking = $tracking;
+	}
+
+	/**
+	 * Returns an array of events this subscriber wants to listen to.
+	 *
+	 * @return array
+	 */
+	public static function get_subscribed_events(): array {
+		return [
+			'backwpup_track_nudge_impression' => [ 'track_nudge_impression', 10, 1 ],
+		];
+	}
+
+	/**
+	 * Track nudge impression event.
+	 *
+	 * @param string $location The nudge location identifier.
+	 *
+	 * @return void
+	 */
+	public function track_nudge_impression( string $location ): void {
+		$this->tracking->track_nudge_impression( $location );
+	}
+}
