+	public function track_locked_option_click( string $storage_slug ): void {
+		$this->nudge_tracking->track_locked_option_click( $storage_slug );
+	}
+
+	/**
+	 * Handle AJAX nudge tracking requests from the front end.
+	 *
+	 * @return void
+	 */
+	public function ajax_track_nudge(): void {
+		check_ajax_referer( 'backwpup_track_nudge', 'nonce' );
+
+		$event   = isset( $_POST['event'] ) ? sanitize_key( wp_unslash( $_POST['event'] ) ) : '';
+		$storage = isset( $_POST['storage'] ) ? sanitize_key( wp_unslash( $_POST['storage'] ) ) : '';
+
+		if ( 'nudge_click' === $event ) {
+			do_action( 'backwpup_track_nudge_click', $storage );
+			wp_send_json_success();
+		} elseif ( 'locked_option_click' === $event ) {
+			do_action( 'backwpup_track_locked_option_click', $storage );
+			wp_send_json_success();
+		}
+
+		wp_send_json_error(
+			[ 'message' => 'Unsupported tracking event.' ],
+			400
+		);
+	}
 }

1	<?php
2	use Inpsyde\Restore\ViewLoader;
3	
4	/**
5	 * Class For BackWPup Jobs page.
6	 */
7	class BackWPup_Page_Jobs extends WP_List_Table {
8	
9		/**
10		 * Nonce action for list filters and sorting.
11		 */
12		private const LIST_NONCE_ACTION = 'backwpup_jobs_list';
13	
14		/**
15		 * Log file path.
16		 *
17		 * @var string
18		 */
19		public static $logfile;
20	
21		/**
22		 * List table object
23		 *
24		 * @var self
25		 */
26		private static $listtable;
27	
28		/**
29		 * Job object.
30		 *
31		 * @var bool|object
32		 */
33		private $job_object;
34	
35		/**
36		 * Job types.
37		 *
38		 * @var array
39		 */
40		private $job_types;
41	
42		/**
43		 * Destinations array.
44		 *
45		 * @var array
46		 */
47		private $destinations;
48	
49		/**
50		 * Constructor.
51		 */
52		public function __construct() {
53			parent::__construct(
54				[
55					'plural'   => 'jobs',
56					'singular' => 'job',
57					'ajax'     => true,
58				]
59				);
60		}
61	
62		/**
63		 * Check if the current user has backwpup capability.
64		 *
65		 * @return bool
66		 */
67		public function ajax_user_can() {
68			return current_user_can( 'backwpup' );
69		}
70	
71		/**
72		 * Get filtered jobs based on the status UI filter.
73		 *
74		 * @return array
75		 */
76		private function get_filtered_jobs() {
77			$jobs = array_filter(
78				BackWPup_Option::get_job_ids(),
79				function ( $job_id ) {
80					return BackWPup_Option::get( $job_id, 'legacy', false );
81				}
82			);
83	
84			// Get the "status" filter value from the GET request.
85			$status_filter = '';
86			$nonce         = $this->get_list_nonce();
87			if ( $nonce && wp_verify_nonce( $nonce, self::LIST_NONCE_ACTION ) ) {
88				$status_filter = filter_input( INPUT_GET, 'status', FILTER_SANITIZE_FULL_SPECIAL_CHARS );
89				if ( null === $status_filter && isset( $_GET['status'] ) ) {
90					$status_filter = sanitize_text_field( wp_unslash( $_GET['status'] ) );
91				} else {
92					$status_filter = $status_filter ? sanitize_text_field( $status_filter ) : '';
93				}
94			}
95			if ( empty( $status_filter ) ) {
96				return $jobs;
97			}
98	
99			return array_filter(
100				$jobs,
101				function ( $job_id ) use ( $status_filter ) {
102					switch ( $status_filter ) {
103						case 'disabled':
104							return empty( BackWPup_Option::get( $job_id, 'activetype', '' ) );
105					}
106					return true;
107				}
108			);
109		}
110	
111		/**
112		 * Prepares the list of items for displaying.
113		 *
114		 * @return void
115		 */
116		public function prepare_items() {
117			$this->items        = $this->get_filtered_jobs();
118			$this->job_object   = BackWPup_Job::get_working_data();
119			$this->job_types    = BackWPup::get_job_types();
120			$this->destinations = BackWPup::get_registered_destinations();
121	
122			$order_param   = '';
123			$orderby_param = '';
124			$nonce         = $this->get_list_nonce();
125			if ( $nonce && wp_verify_nonce( $nonce, self::LIST_NONCE_ACTION ) ) {
126				$order_param = filter_input( INPUT_GET, 'order', FILTER_SANITIZE_FULL_SPECIAL_CHARS );
127				if ( null === $order_param && isset( $_GET['order'] ) ) {
128					$order_param = sanitize_text_field( wp_unslash( $_GET['order'] ) );
129				} else {
130					$order_param = $order_param ? sanitize_text_field( $order_param ) : '';
131				}
132				$order_param = $order_param ? sanitize_key( $order_param ) : '';
133	
134				$orderby_param = filter_input( INPUT_GET, 'orderby', FILTER_SANITIZE_FULL_SPECIAL_CHARS );
135				if ( null === $orderby_param && isset( $_GET['orderby'] ) ) {
136					$orderby_param = sanitize_text_field( wp_unslash( $_GET['orderby'] ) );
137				} else {
138					$orderby_param = $orderby_param ? sanitize_text_field( $orderby_param ) : '';
139				}
140				$orderby_param = $orderby_param ? sanitize_key( $orderby_param ) : '';
141			}
142	
143			if ( empty( $order_param ) || empty( $orderby_param ) ) {
144				return;
145			}
146	
147			if ( 'asc' === strtolower( (string) $order_param ) ) {
148				$order = SORT_ASC;
149			} else {
150				$order = SORT_DESC;
151			}
152	
153			if ( empty( $orderby_param ) || ! in_array( strtolower( (string) $orderby_param ), [ 'jobname', 'type', 'dest', 'next', 'last' ], true ) ) {
154				$orderby = 'jobname';
155			} else {
156				$orderby = strtolower( (string) $orderby_param );
157			}
158	
159			// Sorting.
160			$job_configs = [];
161			$i           = 0;
162	
163			foreach ( $this->items as $item ) {
164				$job_configs[ $i ]['jobid']   = $item;
165				$job_configs[ $i ]['jobname'] = BackWPup_Option::get( $item, 'name' );
166				$job_configs[ $i ]['type']    = BackWPup_Option::get( $item, 'type' );
167				$job_configs[ $i ]['dest']    = BackWPup_Option::get( $item, 'destinations' );
168				if ( SORT_ASC === $order ) {
169					sort( $job_configs[ $i ]['type'] );
170					sort( $job_configs[ $i ]['dest'] );
171				} else {
172					rsort( $job_configs[ $i ]['type'] );
173					rsort( $job_configs[ $i ]['dest'] );
174				}
175				$job_configs[ $i ]['type'] = array_shift( $job_configs[ $i ]['type'] );
176				$job_configs[ $i ]['dest'] = array_shift( $job_configs[ $i ]['dest'] );
177				$job_configs[ $i ]['next'] = (int) wp_next_scheduled( 'backwpup_cron', [ 'arg' => $item ] );
178				$job_configs[ $i ]['last'] = BackWPup_Option::get( $item, 'lastrun' );
179				++$i;
180			}
181	
182			$tmp = [];
183	
184			foreach ( $job_configs as &$ma ) {
185				$tmp[] = &$ma[ $orderby ];
186			}
187			array_multisort( $tmp, $order, $job_configs );
188	
189			$this->items = [];
190	
191			foreach ( $job_configs as $item ) {
192				$this->items[] = $item['jobid'];
193			}
194		}
195	
196		/**
197		 * Message to be displayed when there are no items.
198		 *
199		 * @return void
200		 */
201		public function no_items() {
202			esc_html_e( 'No Legacy Jobs.', 'backwpup' );
203		}
204	
205		/**
206		 * Retrieves the list of bulk actions available for this table.
207		 *
208		 * @return array
209		 */
210		public function get_bulk_actions() {
211			if ( ! $this->has_items() ) {
212				return [];
213			}
214	
215			$actions           = [];
216			$actions['delete'] = __( 'Delete', 'backwpup' );
217	
218			return wpm_apply_filters_typed( 'array', 'backwpup_page_jobs_get_bulk_actions', $actions );
219		}
220	
221		/**
222		 * Gets a list of columns.
223		 *
224		 * @return array
225		 */
226		public function get_columns() {
227			$jobs_columns            = [];
228			$jobs_columns['cb']      = '<input type="checkbox" />';
229			$jobs_columns['jobname'] = __( 'Job Name', 'backwpup' );
230			$jobs_columns['type']    = __( 'Type', 'backwpup' );
231			$jobs_columns['dest']    = __( 'Destinations', 'backwpup' );
232			$jobs_columns['next']    = __( 'Next Run', 'backwpup' );
233			$jobs_columns['last']    = __( 'Last Run', 'backwpup' );
234	
235			return $jobs_columns;
236		}
237	
238		/**
239		 * Gets a list of sortable columns.
240		 *
241		 * @return array
242		 */
243		public function get_sortable_columns() {
244			return [
245				'jobname' => 'jobname',
246				'type'    => 'type',
247				'dest'    => 'dest',
248				'next'    => 'next',
249				'last'    => 'last',
250			];
251		}
252	
253		/**
254		 * Retrieves the table classes for the job page.
255		 *
256		 * This method constructs an array of CSS classes to be applied to the table
257		 * on the job page. The 'fixed' class is intentionally omitted from the default
258		 * classes.
259		 *
260		 * @return array An array of CSS classes for the table.
261		 */
262		protected function get_table_classes() {
263			// Remove 'fixed' from the default classes.
264			$classes = [ 'widefat', 'striped', $this->_args['plural'] ];
265			return $classes;
266		}
267	
268		/**
269		 * The checkbox column.
270		 *
271		 * @param int $item Job ID.
272		 *
273		 * @return string
274		 */
275		public function column_cb( $item ) {
276			return '<input type="checkbox" name="jobs[]" value="' . esc_attr( $item ) . '" />';
277		}
278	
279		/**
280		 * The job name column.
281		 *
282		 * @param int $item Job ID.
283		 *
284		 * @return string
285		 */
286		public function column_jobname( $item ) {
287			$job_normal_hide = '';
288			if ( is_object( $this->job_object ) ) {
289				$job_normal_hide = ' style="display:none;"';
290			}
291	
292			$r = '<strong title="' . sprintf(
293				/* translators: %d: job ID. */
294				__( 'Job ID: %d', 'backwpup' ),
295				$item
296			) . '">' . esc_html( BackWPup_Option::get( $item, 'name' ) ) . '</strong>';
297			$actions = [];
298			if ( current_user_can( 'backwpup_jobs_edit' ) ) {
299				$actions['edit']   = '<a href="' . wp_nonce_url( network_admin_url( 'admin.php' ) . '?page=backwpupeditjob&jobid=' . $item, 'edit-job' ) . '">' . esc_html__( 'Edit', 'backwpup' ) . '</a>';
300				$actions['delete'] = '<a class="submitdelete" href="' . wp_nonce_url( network_admin_url( 'admin.php' ) . '?page=backwpupjobs&action=delete&jobs[]=' . $item, 'bulk-jobs' ) . '" onclick="return showNotice.warn();">' . esc_html__( 'Delete', 'backwpup' ) . '</a>';
301			}
302			if ( current_user_can( 'backwpup_jobs_start' ) ) {
303				$url               = BackWPup_Job::get_jobrun_url( 'runnowlink', $item );
304				$actions['runnow'] = '<a href="' . esc_attr( $url['url'] ) . '">' . esc_html__( 'Run now', 'backwpup' ) . '</a>';
305			}
306			if ( current_user_can( 'backwpup_logs' ) && BackWPup_Option::get( $item, 'logfile' ) ) {
307				$logfile = basename( (string) BackWPup_Option::get( $item, 'logfile' ) );
308				if ( is_object( $this->job_object ) && (int) $this->job_object->job['jobid'] === (int) $item ) {
309					$logfile = basename( (string) $this->job_object->logfile );
310				}
311				$log_name           = str_replace( [ '.html', '.gz' ], '', basename( $logfile ) );
312				$actions['lastlog'] = '<a href="' . admin_url( 'admin-ajax.php' ) . '?&action=backwpup_view_log&log=' . $log_name . '&_ajax_nonce=' . wp_create_nonce( 'view-log_' . $log_name ) . '&amp;TB_iframe=true&amp;width=640&amp;height=440\" title="' . esc_attr( $logfile ) . '" class="thickbox">' . __( 'Last log', 'backwpup' ) . '</a>';
313			}
314			$actions = wpm_apply_filters_typed( 'array', 'backwpup_page_jobs_actions', $actions, $item, false );
315			$r      .= '<div class="job-normal"' . $job_normal_hide . '>' . $this->row_actions( $actions ) . '</div>';
316			if ( is_object( $this->job_object ) ) {
317				$actionsrun = [];
318				$actionsrun = wpm_apply_filters_typed( 'array', 'backwpup_page_jobs_actions', $actionsrun, $item, true );
