392				$job_normal_hide = ' style="display:none;"';
393			}
394			if ( is_object( $this->job_object ) && $this->job_object->job['jobid'] === $item ) {
395				$current_timestamp = time() + (int) ( (float) get_option( 'gmt_offset' ) * HOUR_IN_SECONDS );
396				$runtime           = $current_timestamp - $this->job_object->start_time;
397				$r                .= '<div class="job-run">' . sprintf(
398					/* translators: %s: runtime in seconds. */
399					esc_html__( 'Running for: %s seconds', 'backwpup' ),
400					'<span id="runtime">' . $runtime . '</span>'
401				) . '</div>';
402			}
403			if ( is_object( $this->job_object ) && (int) $this->job_object->job['jobid'] === (int) $item ) {
404				$r .= '<div class="job-normal"' . $job_normal_hide . '>';
405			}
406			if ( 'wpcron' === BackWPup_Option::get( $item, 'activetype' ) ) {
407				$nextrun = wp_next_scheduled( 'backwpup_cron', [ 'arg' => $item ] ) + ( get_option( 'gmt_offset' ) * 3600 );
408				if ( $nextrun ) {
409					// translators: %s: cron expression.
410					$title = sprintf( esc_html__( 'Cron: %s', 'backwpup' ), BackWPup_Option::get( $item, 'cron' ) );
411					// translators: %1$s: date, %2$s: time.
412					$content = sprintf( __( '%1$s at %2$s', 'backwpup' ), wp_date( get_option( 'date_format' ), $nextrun ), wp_date( get_option( 'time_format' ), $nextrun ) );
413					$r      .= '<span title="' . $title . '">' . $content . '</span><br />';
414				} else {
415					$r .= __( 'Not scheduled!', 'backwpup' ) . '<br />';
416				}
417			} elseif ( 'link' === BackWPup_Option::get( $item, 'activetype' ) ) {
418				$r .= __( 'External link', 'backwpup' ) . '<br />';
419			} else {
420				$r .= __( 'Inactive', 'backwpup' );
421			}
422			if ( is_object( $this->job_object ) && (int) $this->job_object->job['jobid'] === (int) $item ) {
423				$r .= '</div>';
424			}
425	
426			return $r;
