482		/**
483		 * Generates download link from url.
484		 *
485		 * @param string $download_url Download url.
486		 * @return string
487		 */
488		private static function generate_download_link( $download_url ) {
489			$params = [];
490			parse_str( wp_parse_url( $download_url, PHP_URL_QUERY ), $params );
491	
492			$file        = $params['file'];
493			$local_file  = untrailingslashit( BackWPup::get_plugin_data( 'TEMP' ) ) . '/' . basename( $params['local_file'] ?? $file );
494			$jobid       = $params['jobid'];
495			$destination = strtoupper( str_replace( 'download', '', $params['action'] ) );
496	
497			// Construct the link.
498			return sprintf(
499				'<a href="#TB_inline?height=300&width=630&inlineId=tb_download_file" 
500	            class="backup-download-link thickbox js-backwpup-download-backup" 
501	            id="backup-download-link"
502	            data-jobid="%1$s" 
503	            data-destination="%2$s" 
504	            data-file="%3$s" 
505	            data-local-file="%4$s" 
506	            data-nonce="%5$s" 
507	            data-url="%6$s">%7$s</a>',
508				intval( $jobid ),
509				esc_attr( $destination ),
510				esc_attr( $file ),
511				esc_attr( $local_file ),
512				wp_create_nonce( 'backwpup_action_nonce' ),
513				wp_nonce_url( $download_url, 'backwpup_action_nonce' ),
514				__( 'Download', 'backwpup' )
515			);
516		}
