518		/**
519		 * Load listing page.
520		 *
521		 * @return void
522		 */
523		public static function load() {
524			// Create table.
525			self::$listtable = new self();
526	
527			if ( empty( self::$listtable->current_action() ) ) {
528				self::ensure_list_nonce();
529			}
530	
531			switch ( self::$listtable->current_action() ) {
532				case 'delete': // Delete job.
533					if ( ! current_user_can( 'backwpup_jobs_edit' ) ) {
534						break;
535					}
536					$jobs = filter_input( INPUT_GET, 'jobs', FILTER_DEFAULT, FILTER_REQUIRE_ARRAY );
537					if ( ! empty( $jobs ) ) {
538						check_admin_referer( 'bulk-jobs' );
539	
540						foreach ( array_map( 'absint', $jobs ) as $jobid ) {
541							wp_clear_scheduled_hook( 'backwpup_cron', [ 'arg' => (int) $jobid ] );
542							BackWPup_Option::delete_job( $jobid );
543						}
544					}
545					break;
546	
547				case 'copy': // Copy job.
548					if ( ! current_user_can( 'backwpup_jobs_edit' ) ) {
549						break;
550					}
551					$old_job_id = absint( filter_input( INPUT_GET, 'jobid', FILTER_SANITIZE_NUMBER_INT ) );
552					if ( $old_job_id < 1 ) {
553						break;
554					}
555					check_admin_referer( 'copy-job_' . $old_job_id );
556					// Create new.
557					$newjobid = BackWPup_Option::get_job_ids();
558					sort( $newjobid );
559					$newjobid    = end( $newjobid ) + 1;
560					$old_options = BackWPup_Option::get_job( $old_job_id );
561	
562					foreach ( $old_options as $key => $option ) {
563						if ( 'jobid' === $key ) {
564							$option = $newjobid;
565						}
566						if ( 'name' === $key ) {
567							$option = __( 'Copy of', 'backwpup' ) . ' ' . $option;
568						}
569						if ( 'activetype' === $key ) {
570							$option = '';
571						}
572						if ( 'archivename' === $key ) {
573							$option = str_replace( $old_job_id, $newjobid, (string) $option );
574						}
575						if ( 'logfile' === $key || 'lastbackupdownloadurl' === $key || 'lastruntime' === $key || 'lastrun' === $key ) {
576							continue;
577						}
578						BackWPup_Option::update( $newjobid, $key, $option );
579					}
580					break;
581	
582				case 'runnow':
583					$jobid = absint( filter_input( INPUT_GET, 'jobid', FILTER_SANITIZE_NUMBER_INT ) );
584					if ( $jobid ) {
585						if ( ! current_user_can( 'backwpup_jobs_start' ) ) {
586							wp_die( esc_html__( 'Sorry, you don\'t have permissions to do that.', 'backwpup' ) );
587						}
588						check_admin_referer( 'backwpup_job_run-runnowlink' );
589	
590						// Check temp folder.
591						$temp_folder_message = BackWPup_File::check_folder( BackWPup::get_plugin_data( 'TEMP' ), true );
592						BackWPup_Admin::message( $temp_folder_message, true );
593						// Check log folder.
594						$log_folder         = get_site_option( 'backwpup_cfg_logfolder' );
595						$log_folder         = BackWPup_File::get_absolute_path( $log_folder );
596						$log_folder_message = BackWPup_File::check_folder( $log_folder );
597						BackWPup_Admin::message( $log_folder_message, true );
598						// Check backup destinations.
599						$job_types      = BackWPup::get_job_types();
600						$job_conf_types = BackWPup_Option::get( $jobid, 'type' );
601						$creates_file   = false;
602	
603						foreach ( $job_types as $id => $job_type_class ) {
604							if ( in_array( $id, $job_conf_types, true ) && $job_type_class->creates_file() ) {
605								$creates_file = true;
606								break;
607							}
608						}
609						if ( $creates_file ) {
610							$job_conf_dests = BackWPup_Option::get( $jobid, 'destinations' );
611							$destinations   = 0;
612	
613							foreach ( BackWPup::get_registered_destinations() as $id => $dest ) {
614								if ( ! in_array( $id, $job_conf_dests, true ) || empty( $dest['class'] ) ) {
615									continue;
616								}
617	
618								/* @var BackWPup_Destinations $dest_class */
619								$dest_class   = BackWPup::get_destination( $id );
620								$job_settings = BackWPup_Option::get_job( $jobid );
621								if ( ! $dest_class->can_run( $job_settings, false ) ) {
622									BackWPup_Admin::message(
623										sprintf(
624											/* translators: 1: job name, 2: destination name. */
625											__( 'The job "%1$s" destination "%2$s" is not configured properly', 'backwpup' ),
626											esc_attr( BackWPup_Option::get( $jobid, 'name' ) ),
627											$id
628										),
629										true
630									);
631								}
632								++$destinations;
633							}
634							if ( $destinations < 1 ) {
635								BackWPup_Admin::message(
636									sprintf(
637										/* translators: %s: job name. */
638										__( 'The job "%s" needs properly configured destinations to run!', 'backwpup' ),
639										esc_attr( BackWPup_Option::get( $jobid, 'name' ) )
640									),
641									true
642								);
643							}
644						}
645	
646						// Only start job if messages empty.
647						$log_messages = BackWPup_Admin::get_messages();
648	
649						if ( empty( $log_messages ) ) {
650							$old_log_file = BackWPup_Option::get( $jobid, 'logfile' );
651							BackWPup_Job::get_jobrun_url( 'runnow', $jobid );
652							usleep( 250000 ); // Wait a quarter second.
653							$new_log_file = BackWPup_Option::get( $jobid, 'logfile', null, false );
654							// Sleep as long as job not started.
655							$i = 0;
656	
657							while ( $old_log_file === $new_log_file ) {
658								usleep( 250000 ); // Wait a quarter second for next try.
659								$new_log_file = BackWPup_Option::get( $jobid, 'logfile', null, false );
660								// Wait maximal 10 sec.
661								if ( $i >= 40 ) {
662									BackWPup_Admin::message(
663										sprintf(
664											/* translators: 1: Job name, 2: Information URL */
665											__( 'Job "%1$s" has started, but not responded for 10 seconds. Please check <a href="%2$s">information</a>.', 'backwpup' ),
666											esc_attr( BackWPup_Option::get( $jobid, 'name' ) ),
667											network_admin_url( 'admin.php' ) . '?page=backwpupsettings#backwpup-tab-information'
668										),
669										true
670									);
671									break 2;
672								}
673								++$i;
674							}
675							BackWPup_Admin::message(
676								sprintf(
677									/* translators: %s: Job name */
678									__( 'Job "%s" started.', 'backwpup' ),
679									esc_attr( BackWPup_Option::get( $jobid, 'name' ) )
680								)
681							);
682						}
683					}
684					break;
685	
686				case 'abort': // Abort job.
687					if ( ! current_user_can( 'backwpup_jobs_start' ) ) {
688						break;
689					}
690					check_admin_referer( 'abort-job' );
691					if ( ! file_exists( BackWPup::get_plugin_data( 'running_file' ) ) ) {
692						break;
693					}
694					// Abort.
695					BackWPup_Job::user_abort();
696					BackWPup_Admin::message( __( 'Job will be terminated.', 'backwpup' ) );
697					break;
698	
699				default:
700					do_action( 'backwpup_page_jobs_load', self::$listtable->current_action() );
701					break;
702			}
703	
704			self::$listtable->prepare_items();
705		}
