1251		 * Render log HTML through the shared log renderer when available.
1252		 *
1253		 * @param string $content Raw HTML log file fragment.
1254		 *
1255		 * @return string
1256		 */
1257		private static function render_log_content( string $content ): string {
1258			$container = wpm_apply_filters_typed( '?object', 'backwpup_container', null );
1259			if ( is_object( $container ) && method_exists( $container, 'has' ) && $container->has( 'log_facade' ) ) {
1260				$log_facade = $container->get( 'log_facade' );
1261				if ( is_object( $log_facade ) && method_exists( $log_facade, 'render_html' ) ) {
1262					return $log_facade->render_html( $content );
1263				}
1264			}
1265	
1266			$log_facade = new \WPMedia\BackWPup\Log\LogFacade();
1267			return $log_facade->render_html( $content );
1268		}
