1270		/**
1271		 * Get log file path.
1272		 *
1273		 * @param string      $folder Folder Path.
1274		 * @param string|null $filename Filename.
1275		 * @return string
1276		 *
1277		 * @throws \InvalidArgumentException When empty filename.
1278		 */
1279		private static function get_logfile_path( string $folder, ?string $filename ): string {
1280			if ( ! $filename ) {
1281				throw new \InvalidArgumentException( 'Log file cannot be null.' );
1282			}
1283	
1284			$filename = basename( trim( $filename ) );
1285	
1286			if (
1287				preg_match( '/^[a-zA-Z0-9_-]+\.[a-zA-Z0-9]{1,5}$/', $filename ) === 0
1288				|| strpos( $filename, 'backwpup_log_' ) === false
1289			) {
1290				throw new \InvalidArgumentException( 'Invalidly formatted log filename passed.' );
1291			}
1292	
1293			return $folder . $filename;
1294		}
