1358		 *
1359		 * @return bool
1360		 */
1361		private function get_list_nonce() {
1362			$nonce = filter_input( INPUT_GET, '_wpnonce', FILTER_SANITIZE_FULL_SPECIAL_CHARS );
1363			if ( null === $nonce && isset( $_GET['_wpnonce'] ) ) {
1364				$nonce = sanitize_text_field( wp_unslash( $_GET['_wpnonce'] ) );
1365			} else {
1366				$nonce = $nonce ? sanitize_text_field( $nonce ) : '';
1367			}
1368			if ( ! $nonce || ! wp_verify_nonce( $nonce, self::LIST_NONCE_ACTION ) ) {
1369				return '';
1370			}
1371	
1372			return (string) $nonce;
1373		}
1374	}
